using NUnit.Framework;

[TestFixture]
public class FindLargestOddTests
{
    [Test]
    public void Returns_Largest_Odd()
    {
        var result = FindLargestOdd(new[] { 8, 3, 10, 5, 11 });
        Assert.That(result, Is.EqualTo(11));
    }

    private int? FindLargestOdd(int[] nums)
    {
        int? best = null;

        foreach (var num in nums)
        {
            if (num % 2 != 0 && (best == null || num > best))
                best = num;
        }

        return best;
    }
}
